00778     sscanf(bd->GlslVersionString, "#version %d", &glsl_version);
00779 
00780     const GLchar* vertex_shader_glsl_120 =
00781         "uniform mat4 ProjMtx;\n"
00782         "attribute vec2 Position;\n"
00783         "attribute vec2 UV;\n"
00784         "attribute vec4 Color;\n"
00785         "varying vec2 Frag_UV;\n"
00786         "varying vec4 Frag_Color;\n"
00787         "void main()\n"
00788         "{\n"
00789         "    Frag_UV = UV;\n"
00790         "    Frag_Color = Color;\n"
00791         "    gl_Position = ProjMtx * vec4(Position.xy,0,1);\n"
00792         "}\n";
00793 
00794     const GLchar* vertex_shader_glsl_130 =
00795         "uniform mat4 ProjMtx;\n"
00796         "in vec2 Position;\n"
00797         "in vec2 UV;\n"
00798         "in vec4 Color;\n"
00799         "out vec2 Frag_UV;\n"
00800         "out vec4 Frag_Color;\n"
00801         "void main()\n"
00802         "{\n"
00803         "    Frag_UV = UV;\n"
00804         "    Frag_Color = Color;\n"
00805         "    gl_Position = ProjMtx * vec4(Position.xy,0,1);\n"
00806         "}\n";
00807 
00808     const GLchar* vertex_shader_glsl_300_es =
00809         "precision highp float;\n"
00810         "layout (location = 0) in vec2 Position;\n"
00811         "layout (location = 1) in vec2 UV;\n"
00812         "layout (location = 2) in vec4 Color;\n"
00813         "uniform mat4 ProjMtx;\n"
00814         "out vec2 Frag_UV;\n"
00815         "out vec4 Frag_Color;\n"
00816         "void main()\n"
00817         "{\n"
00818         "    Frag_UV = UV;\n"
00819         "    Frag_Color = Color;\n"
00820         "    gl_Position = ProjMtx * vec4(Position.xy,0,1);\n"
00821         "}\n";
00822 
00823     const GLchar* vertex_shader_glsl_410_core =
00824         "layout (location = 0) in vec2 Position;\n"
00825         "layout (location = 1) in vec2 UV;\n"
00826         "layout (location = 2) in vec4 Color;\n"
00827         "uniform mat4 ProjMtx;\n"
00828         "out vec2 Frag_UV;\n"
00829         "out vec4 Frag_Color;\n"
00830         "void main()\n"
00831         "{\n"
00832         "    Frag_UV = UV;\n"
00833         "    Frag_Color = Color;\n"
00834         "    gl_Position = ProjMtx * vec4(Position.xy,0,1);\n"
00835         "}\n";
