00837     const GLchar* fragment_shader_glsl_120 =
00838         "#ifdef GL_ES\n"
00839         "    precision mediump float;\n"
00840         "#endif\n"
00841         "uniform sampler2D Texture;\n"
00842         "varying vec2 Frag_UV;\n"
00843         "varying vec4 Frag_Color;\n"
00844         "void main()\n"
00845         "{\n"
00846         "    gl_FragColor = Frag_Color * texture2D(Texture, Frag_UV.st);\n"
00847         "}\n";
00848 
00849     const GLchar* fragment_shader_glsl_130 =
00850         "uniform sampler2D Texture;\n"
00851         "in vec2 Frag_UV;\n"
00852         "in vec4 Frag_Color;\n"
00853         "out vec4 Out_Color;\n"
00854         "void main()\n"
00855         "{\n"
00856         "    Out_Color = Frag_Color * texture(Texture, Frag_UV.st);\n"
00857         "}\n";
00858 
00859     const GLchar* fragment_shader_glsl_300_es =
00860         "precision mediump float;\n"
00861         "uniform sampler2D Texture;\n"
00862         "in vec2 Frag_UV;\n"
00863         "in vec4 Frag_Color;\n"
00864         "layout (location = 0) out vec4 Out_Color;\n"
00865         "void main()\n"
00866         "{\n"
00867         "    Out_Color = Frag_Color * texture(Texture, Frag_UV.st);\n"
00868         "}\n";
00869 
00870     const GLchar* fragment_shader_glsl_410_core =
00871         "in vec2 Frag_UV;\n"
00872         "in vec4 Frag_Color;\n"
00873         "uniform sampler2D Texture;\n"
00874         "layout (location = 0) out vec4 Out_Color;\n"
00875         "void main()\n"
00876         "{\n"
00877         "    Out_Color = Frag_Color * texture(Texture, Frag_UV.st);\n"
00878         "}\n";
00879 
00880     // Select shaders matching our GLSL versions
00881     const GLchar* vertex_shader = nullptr;
00882     const GLchar* fragment_shader = nullptr;
00883     if (glsl_version < 130)
00884     {
00885         vertex_shader = vertex_shader_glsl_120;
00886         fragment_shader = fragment_shader_glsl_120;
00887     }
00888     else if (glsl_version >= 410)
00889     {
00890         vertex_shader = vertex_shader_glsl_410_core;
00891         fragment_shader = fragment_shader_glsl_410_core;
00892     }
00893     else if (glsl_version == 300)
00894     {
00895         vertex_shader = vertex_shader_glsl_300_es;
00896         fragment_shader = fragment_shader_glsl_300_es;
00897     }
00898     else
00899     {
00900         vertex_shader = vertex_shader_glsl_130;
00901         fragment_shader = fragment_shader_glsl_130;
00902     }
00903 
00904     // Create shaders
00905     const GLchar* vertex_shader_with_version[2] = { bd->GlslVersionString, vertex_shader };
00906     GLuint vert_handle = glCreateShader(GL_VERTEX_SHADER);
00907     glShaderSource(vert_handle, 2, vertex_shader_with_version, nullptr);
00908     glCompileShader(vert_handle);
00909     CheckShader(vert_handle, "vertex shader");
00910 
00911     const GLchar* fragment_shader_with_version[2] = { bd->GlslVersionString, fragment_shader };
00912     GLuint frag_handle = glCreateShader(GL_FRAGMENT_SHADER);
00913     glShaderSource(frag_handle, 2, fragment_shader_with_version, nullptr);
00914     glCompileShader(frag_handle);
00915     CheckShader(frag_handle, "fragment shader");
00916 
00917     // Link
00918     bd->ShaderHandle = glCreateProgram();
00919     glAttachShader(bd->ShaderHandle, vert_handle);
00920     glAttachShader(bd->ShaderHandle, frag_handle);
00921     glLinkProgram(bd->ShaderHandle);
00922     CheckProgram(bd->ShaderHandle, "shader program");
00923 
00924     glDetachShader(bd->ShaderHandle, vert_handle);
00925     glDetachShader(bd->ShaderHandle, frag_handle);
00926     glDeleteShader(vert_handle);
00927     glDeleteShader(frag_handle);
00928 
00929     bd->AttribLocationTex = glGetUniformLocation(bd->ShaderHandle, "Texture");
00930     bd->AttribLocationProjMtx = glGetUniformLocation(bd->ShaderHandle, "ProjMtx");
00931     bd->AttribLocationVtxPos = (GLuint)glGetAttribLocation(bd->ShaderHandle, "Position");
00932     bd->AttribLocationVtxUV = (GLuint)glGetAttribLocation(bd->ShaderHandle, "UV");
00933     bd->AttribLocationVtxColor = (GLuint)glGetAttribLocation(bd->ShaderHandle, "Color");
00934 
00935     // Create buffers
00936     glGenBuffers(1, &bd->VboHandle);
00937     glGenBuffers(1, &bd->ElementsHandle);
00938 
00939     ImGui_ImplOpenGL3_CreateFontsTexture();
00940 
00941     // Restore modified GL state
00942     glBindTexture(GL_TEXTURE_2D, last_texture);
00943     glBindBuffer(GL_ARRAY_BUFFER, last_array_buffer);
00944 #ifdef IMGUI_IMPL_OPENGL_MAY_HAVE_BIND_BUFFER_PIXEL_UNPACK
00945     if (bd->GlVersion >= 210) { glBindBuffer(GL_PIXEL_UNPACK_BUFFER, last_pixel_unpack_buffer); }
00946 #endif
00947 #ifdef IMGUI_IMPL_OPENGL_USE_VERTEX_ARRAY
00948     glBindVertexArray(last_vertex_array);
00949 #endif
00950 
00951     return true;
00952 }

00678 {
00679     ImGuiIO& io = ImGui::GetIO();
00680     ImGui_ImplOpenGL3_Data* bd = ImGui_ImplOpenGL3_GetBackendData();
00681 
00682     // Build texture atlas
00683     unsigned char* pixels;
00684     int width, height;
00685     io.Fonts->GetTexDataAsRGBA32(&pixels, &width, &height);   // Load as RGBA 32-bit (75% of the memory is wasted, but default font is so small) because it is more likely to be compatible with user's existing shaders. If your ImTextureId represent a higher-level concept than just a GL texture id, consider calling GetTexDataAsAlpha8() instead to save on GPU memory.
00686 
00687     // Upload texture to graphics system
00688     // (Bilinear sampling is required by default. Set 'io.Fonts->Flags |= ImFontAtlasFlags_NoBakedLines' or 'style.AntiAliasedLinesUseTex = false' to allow point/nearest sampling)
00689     GLint last_texture;
00690     GL_CALL(glGetIntegerv(GL_TEXTURE_BINDING_2D, &last_texture));
00691     GL_CALL(glGenTextures(1, &bd->FontTexture));
00692     GL_CALL(glBindTexture(GL_TEXTURE_2D, bd->FontTexture));
00693     GL_CALL(glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR));
00694     GL_CALL(glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR));
00695 #ifdef GL_UNPACK_ROW_LENGTH // Not on WebGL/ES
00696     GL_CALL(glPixelStorei(GL_UNPACK_ROW_LENGTH, 0));
00697 #endif
00698     GL_CALL(glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, width, height, 0, GL_RGBA, GL_UNSIGNED_BYTE, pixels));
00699 
00700     // Store our identifier
00701     io.Fonts->SetTexID((ImTextureID)(intptr_t)bd->FontTexture);
00702 
00703     // Restore state
00704     GL_CALL(glBindTexture(GL_TEXTURE_2D, last_texture));
00705 
00706     return true;
00707 }

