00289     // Initialize our loader
00290 #if !defined(IMGUI_IMPL_OPENGL_ES2) && !defined(IMGUI_IMPL_OPENGL_ES3) && !defined(IMGUI_IMPL_OPENGL_LOADER_CUSTOM)
00291     if (imgl3wInit() != 0)
00292     {
00293         fprintf(stderr, "Failed to initialize OpenGL loader!\n");
00294         return false;
00295     }
00296 #endif
00297 
00298     // Setup backend capabilities flags
00299     ImGui_ImplOpenGL3_Data* bd = IM_NEW(ImGui_ImplOpenGL3_Data)();
00300     io.BackendRendererUserData = (void*)bd;
00301     io.BackendRendererName = "imgui_impl_opengl3";
00302 
00303     // Query for GL version (e.g. 320 for GL 3.2)
00304 #if defined(IMGUI_IMPL_OPENGL_ES2)
00305     // GLES 2
00306     bd->GlVersion = 200;
00307     bd->GlProfileIsES2 = true;
00308 #else
00309     // Desktop or GLES 3
00310     const char* gl_version_str = (const char*)glGetString(GL_VERSION);
00311     GLint major = 0;
00312     GLint minor = 0;
00313     glGetIntegerv(GL_MAJOR_VERSION, &major);
00314     glGetIntegerv(GL_MINOR_VERSION, &minor);
00315     if (major == 0 && minor == 0)
00316         sscanf(gl_version_str, "%d.%d", &major, &minor); // Query GL_VERSION in desktop GL 2.x, the string will start with "<major>.<minor>"
00317     bd->GlVersion = (GLuint)(major * 100 + minor * 10);
00318 #if defined(GL_CONTEXT_PROFILE_MASK)
00319     if (bd->GlVersion >= 320)
00320         glGetIntegerv(GL_CONTEXT_PROFILE_MASK, &bd->GlProfileMask);
00321     bd->GlProfileIsCompat = (bd->GlProfileMask & GL_CONTEXT_COMPATIBILITY_PROFILE_BIT) != 0;
00322 #endif
00323 
00324 #if defined(IMGUI_IMPL_OPENGL_ES3)
00325     bd->GlProfileIsES3 = true;
00326 #else
00327     if (strncmp(gl_version_str, "OpenGL ES 3", 11) == 0)
00328         bd->GlProfileIsES3 = true;
00329 #endif
00330 
00331     bd->UseBufferSubData = false;
00332     /*
00333     // Query vendor to enable glBufferSubData kludge
00334 #ifdef _WIN32
00335     if (const char* vendor = (const char*)glGetString(GL_VENDOR))
00336         if (strncmp(vendor, "Intel", 5) == 0)
00337             bd->UseBufferSubData = true;
00338 #endif
00339     */
00340 #endif
00341 
00342 #ifdef IMGUI_IMPL_OPENGL_DEBUG
00343     printf("GlVersion = %d, \"%s\"\nGlProfileIsCompat = %d\nGlProfileMask = 0x%X\nGlProfileIsES2 = %d, GlProfileIsES3 = %d\nGL_VENDOR = '%s'\nGL_RENDERER = '%s'\n", bd->GlVersion, gl_version_str, bd->GlProfileIsCompat, bd->GlProfileMask, bd->GlProfileIsES2, bd->GlProfileIsES3, (const char*)glGetString(GL_VENDOR), (const char*)glGetString(GL_RENDERER)); // [DEBUG]
00344 #endif
00345 
00346 #ifdef IMGUI_IMPL_OPENGL_MAY_HAVE_VTX_OFFSET
00347     if (bd->GlVersion >= 320)
00348         io.BackendFlags |= ImGuiBackendFlags_RendererHasVtxOffset;  // We can honor the ImDrawCmd::VtxOffset field, allowing for large meshes.
00349 #endif
00350     io.BackendFlags |= ImGuiBackendFlags_RendererHasViewports;  // We can create multi-viewports on the Renderer side (optional)
00351 
00352     // Store GLSL version string so we can refer to it later in case we recreate shaders.
00353     // Note: GLSL version is NOT the same as GL version. Leave this to nullptr if unsure.
00354     if (glsl_version == nullptr)
00355     {
00356 #if defined(IMGUI_IMPL_OPENGL_ES2)
00357         glsl_version = "#version 100";
00358 #elif defined(IMGUI_IMPL_OPENGL_ES3)
00359         glsl_version = "#version 300 es";
00360 #elif defined(__APPLE__)
00361         glsl_version = "#version 150";
00362 #else
00363         glsl_version = "#version 130";
00364 #endif
00365     }
00366     IM_ASSERT((int)strlen(glsl_version) + 2 < IM_ARRAYSIZE(bd->GlslVersionString));
00367     strcpy(bd->GlslVersionString, glsl_version);
00368     strcat(bd->GlslVersionString, "\n");
00369 
00370     // Make an arbitrary GL call (we don't actually need the result)
00371     // IF YOU GET A CRASH HERE: it probably means the OpenGL function loader didn't do its job. Let us know!
00372     GLint current_texture;
00373     glGetIntegerv(GL_TEXTURE_BINDING_2D, &current_texture);
00374 
00375     // Detect extensions we support
00376 #ifdef IMGUI_IMPL_OPENGL_MAY_HAVE_POLYGON_MODE
00377     bd->HasPolygonMode = (!bd->GlProfileIsES2 && !bd->GlProfileIsES3);
00378 #endif
00379     bd->HasClipOrigin = (bd->GlVersion >= 450);
00380 #ifdef IMGUI_IMPL_OPENGL_HAS_EXTENSIONS
00381     GLint num_extensions = 0;
00382     glGetIntegerv(GL_NUM_EXTENSIONS, &num_extensions);
00383     for (GLint i = 0; i < num_extensions; i++)
00384     {
00385         const char* extension = (const char*)glGetStringi(GL_EXTENSIONS, i);
00386         if (extension != nullptr && strcmp(extension, "GL_ARB_clip_control") == 0)
00387             bd->HasClipOrigin = true;
00388     }
00389 #endif
00390 
00391     if (io.ConfigFlags & ImGuiConfigFlags_ViewportsEnable)
00392         ImGui_ImplOpenGL3_InitPlatformInterface();
00393 
00394     return true;
00395 }

