00500 {
00501     // Avoid rendering when minimized, scale coordinates for retina displays (screen coordinates != framebuffer coordinates)
00502     int fb_width = (int)(draw_data->DisplaySize.x * draw_data->FramebufferScale.x);
00503     int fb_height = (int)(draw_data->DisplaySize.y * draw_data->FramebufferScale.y);
00504     if (fb_width <= 0 || fb_height <= 0)
00505         return;
00506 
00507     ImGui_ImplOpenGL3_Data* bd = ImGui_ImplOpenGL3_GetBackendData();
00508 
00509     // Backup GL state
00510     GLenum last_active_texture; glGetIntegerv(GL_ACTIVE_TEXTURE, (GLint*)&last_active_texture);
00511     glActiveTexture(GL_TEXTURE0);
00512     GLuint last_program; glGetIntegerv(GL_CURRENT_PROGRAM, (GLint*)&last_program);
00513     GLuint last_texture; glGetIntegerv(GL_TEXTURE_BINDING_2D, (GLint*)&last_texture);
00514 #ifdef IMGUI_IMPL_OPENGL_MAY_HAVE_BIND_SAMPLER
00515     GLuint last_sampler; if (bd->GlVersion >= 330 || bd->GlProfileIsES3) { glGetIntegerv(GL_SAMPLER_BINDING, (GLint*)&last_sampler); } else { last_sampler = 0; }
00516 #endif
00517     GLuint last_array_buffer; glGetIntegerv(GL_ARRAY_BUFFER_BINDING, (GLint*)&last_array_buffer);
00518 #ifndef IMGUI_IMPL_OPENGL_USE_VERTEX_ARRAY
00519     // This is part of VAO on OpenGL 3.0+ and OpenGL ES 3.0+.
00520     GLint last_element_array_buffer; glGetIntegerv(GL_ELEMENT_ARRAY_BUFFER_BINDING, &last_element_array_buffer);
00521     ImGui_ImplOpenGL3_VtxAttribState last_vtx_attrib_state_pos; last_vtx_attrib_state_pos.GetState(bd->AttribLocationVtxPos);
00522     ImGui_ImplOpenGL3_VtxAttribState last_vtx_attrib_state_uv; last_vtx_attrib_state_uv.GetState(bd->AttribLocationVtxUV);
00523     ImGui_ImplOpenGL3_VtxAttribState last_vtx_attrib_state_color; last_vtx_attrib_state_color.GetState(bd->AttribLocationVtxColor);
00524 #endif
00525 #ifdef IMGUI_IMPL_OPENGL_USE_VERTEX_ARRAY
00526     GLuint last_vertex_array_object; glGetIntegerv(GL_VERTEX_ARRAY_BINDING, (GLint*)&last_vertex_array_object);
00527 #endif
00528 #ifdef IMGUI_IMPL_OPENGL_MAY_HAVE_POLYGON_MODE
00529     GLint last_polygon_mode[2]; if (bd->HasPolygonMode) { glGetIntegerv(GL_POLYGON_MODE, last_polygon_mode); }
00530 #endif
00531     GLint last_viewport[4]; glGetIntegerv(GL_VIEWPORT, last_viewport);
00532     GLint last_scissor_box[4]; glGetIntegerv(GL_SCISSOR_BOX, last_scissor_box);
00533     GLenum last_blend_src_rgb; glGetIntegerv(GL_BLEND_SRC_RGB, (GLint*)&last_blend_src_rgb);
00534     GLenum last_blend_dst_rgb; glGetIntegerv(GL_BLEND_DST_RGB, (GLint*)&last_blend_dst_rgb);
00535     GLenum last_blend_src_alpha; glGetIntegerv(GL_BLEND_SRC_ALPHA, (GLint*)&last_blend_src_alpha);
00536     GLenum last_blend_dst_alpha; glGetIntegerv(GL_BLEND_DST_ALPHA, (GLint*)&last_blend_dst_alpha);
00537     GLenum last_blend_equation_rgb; glGetIntegerv(GL_BLEND_EQUATION_RGB, (GLint*)&last_blend_equation_rgb);
00538     GLenum last_blend_equation_alpha; glGetIntegerv(GL_BLEND_EQUATION_ALPHA, (GLint*)&last_blend_equation_alpha);
00539     GLboolean last_enable_blend = glIsEnabled(GL_BLEND);
00540     GLboolean last_enable_cull_face = glIsEnabled(GL_CULL_FACE);
00541     GLboolean last_enable_depth_test = glIsEnabled(GL_DEPTH_TEST);
00542     GLboolean last_enable_stencil_test = glIsEnabled(GL_STENCIL_TEST);
00543     GLboolean last_enable_scissor_test = glIsEnabled(GL_SCISSOR_TEST);
00544 #ifdef IMGUI_IMPL_OPENGL_MAY_HAVE_PRIMITIVE_RESTART
00545     GLboolean last_enable_primitive_restart = (bd->GlVersion >= 310) ? glIsEnabled(GL_PRIMITIVE_RESTART) : GL_FALSE;
00546 #endif
00547 
00548     // Setup desired GL state
00549     // Recreate the VAO every time (this is to easily allow multiple GL contexts to be rendered to. VAO are not shared among GL contexts)
00550     // The renderer would actually work without any VAO bound, but then our VertexAttrib calls would overwrite the default one currently bound.
00551     GLuint vertex_array_object = 0;
00552 #ifdef IMGUI_IMPL_OPENGL_USE_VERTEX_ARRAY
00553     GL_CALL(glGenVertexArrays(1, &vertex_array_object));
00554 #endif
00555     ImGui_ImplOpenGL3_SetupRenderState(draw_data, fb_width, fb_height, vertex_array_object);
00556 
00557     // Will project scissor/clipping rectangles into framebuffer space
00558     ImVec2 clip_off = draw_data->DisplayPos;         // (0,0) unless using multi-viewports
00559     ImVec2 clip_scale = draw_data->FramebufferScale; // (1,1) unless using retina display which are often (2,2)
00560 
00561     // Render command lists
00562     for (int n = 0; n < draw_data->CmdListsCount; n++)
00563     {
00564         const ImDrawList* cmd_list = draw_data->CmdLists[n];
00565 
00566         // Upload vertex/index buffers
00567         // - OpenGL drivers are in a very sorry state nowadays....
00568         //   During 2021 we attempted to switch from glBufferData() to orphaning+glBufferSubData() following reports
00569         //   of leaks on Intel GPU when using multi-viewports on Windows.
00570         // - After this we kept hearing of various display corruptions issues. We started disabling on non-Intel GPU, but issues still got reported on Intel.
00571         // - We are now back to using exclusively glBufferData(). So bd->UseBufferSubData IS ALWAYS FALSE in this code.
00572         //   We are keeping the old code path for a while in case people finding new issues may want to test the bd->UseBufferSubData path.
00573         // - See https://github.com/ocornut/imgui/issues/4468 and please report any corruption issues.
00574         const GLsizeiptr vtx_buffer_size = (GLsizeiptr)cmd_list->VtxBuffer.Size * (int)sizeof(ImDrawVert);
00575         const GLsizeiptr idx_buffer_size = (GLsizeiptr)cmd_list->IdxBuffer.Size * (int)sizeof(ImDrawIdx);
00576         if (bd->UseBufferSubData)
00577         {
00578             if (bd->VertexBufferSize < vtx_buffer_size)
00579             {
00580                 bd->VertexBufferSize = vtx_buffer_size;
00581                 GL_CALL(glBufferData(GL_ARRAY_BUFFER, bd->VertexBufferSize, nullptr, GL_STREAM_DRAW));
00582             }
00583             if (bd->IndexBufferSize < idx_buffer_size)
00584             {
00585                 bd->IndexBufferSize = idx_buffer_size;
00586                 GL_CALL(glBufferData(GL_ELEMENT_ARRAY_BUFFER, bd->IndexBufferSize, nullptr, GL_STREAM_DRAW));
00587             }
00588             GL_CALL(glBufferSubData(GL_ARRAY_BUFFER, 0, vtx_buffer_size, (const GLvoid*)cmd_list->VtxBuffer.Data));
00589             GL_CALL(glBufferSubData(GL_ELEMENT_ARRAY_BUFFER, 0, idx_buffer_size, (const GLvoid*)cmd_list->IdxBuffer.Data));
00590         }
00591         else
00592         {
00593             GL_CALL(glBufferData(GL_ARRAY_BUFFER, vtx_buffer_size, (const GLvoid*)cmd_list->VtxBuffer.Data, GL_STREAM_DRAW));
00594             GL_CALL(glBufferData(GL_ELEMENT_ARRAY_BUFFER, idx_buffer_size, (const GLvoid*)cmd_list->IdxBuffer.Data, GL_STREAM_DRAW));
00595         }
00596 
00597         for (int cmd_i = 0; cmd_i < cmd_list->CmdBuffer.Size; cmd_i++)
00598         {
00599             const ImDrawCmd* pcmd = &cmd_list->CmdBuffer[cmd_i];
00600             if (pcmd->UserCallback != nullptr)
00601             {
00602                 // User callback, registered via ImDrawList::AddCallback()
00603                 // (ImDrawCallback_ResetRenderState is a special callback value used by the user to request the renderer to reset render state.)
00604                 if (pcmd->UserCallback == ImDrawCallback_ResetRenderState)
00605                     ImGui_ImplOpenGL3_SetupRenderState(draw_data, fb_width, fb_height, vertex_array_object);
00606                 else
00607                     pcmd->UserCallback(cmd_list, pcmd);
00608             }
00609             else
00610             {
00611                 // Project scissor/clipping rectangles into framebuffer space
00612                 ImVec2 clip_min((pcmd->ClipRect.x - clip_off.x) * clip_scale.x, (pcmd->ClipRect.y - clip_off.y) * clip_scale.y);
00613                 ImVec2 clip_max((pcmd->ClipRect.z - clip_off.x) * clip_scale.x, (pcmd->ClipRect.w - clip_off.y) * clip_scale.y);
00614                 if (clip_max.x <= clip_min.x || clip_max.y <= clip_min.y)
00615                     continue;
00616 
00617                 // Apply scissor/clipping rectangle (Y is inverted in OpenGL)
00618                 GL_CALL(glScissor((int)clip_min.x, (int)((float)fb_height - clip_max.y), (int)(clip_max.x - clip_min.x), (int)(clip_max.y - clip_min.y)));
00619 
00620                 // Bind texture, Draw
00621                 GL_CALL(glBindTexture(GL_TEXTURE_2D, (GLuint)(intptr_t)pcmd->GetTexID()));
00622 #ifdef IMGUI_IMPL_OPENGL_MAY_HAVE_VTX_OFFSET
00623                 if (bd->GlVersion >= 320)
00624                     GL_CALL(glDrawElementsBaseVertex(GL_TRIANGLES, (GLsizei)pcmd->ElemCount, sizeof(ImDrawIdx) == 2 ? GL_UNSIGNED_SHORT : GL_UNSIGNED_INT, (void*)(intptr_t)(pcmd->IdxOffset * sizeof(ImDrawIdx)), (GLint)pcmd->VtxOffset));
00625                 else
00626 #endif
00627                 GL_CALL(glDrawElements(GL_TRIANGLES, (GLsizei)pcmd->ElemCount, sizeof(ImDrawIdx) == 2 ? GL_UNSIGNED_SHORT : GL_UNSIGNED_INT, (void*)(intptr_t)(pcmd->IdxOffset * sizeof(ImDrawIdx))));
00628             }
00629         }
00630     }
00631 
00632     // Destroy the temporary VAO
00633 #ifdef IMGUI_IMPL_OPENGL_USE_VERTEX_ARRAY
00634     GL_CALL(glDeleteVertexArrays(1, &vertex_array_object));
00635 #endif
00636 
00637     // Restore modified GL state
00638     // This "glIsProgram()" check is required because if the program is "pending deletion" at the time of binding backup, it will have been deleted by now and will cause an OpenGL error. See #6220.
00639     if (last_program == 0 || glIsProgram(last_program)) glUseProgram(last_program);
00640     glBindTexture(GL_TEXTURE_2D, last_texture);
00641 #ifdef IMGUI_IMPL_OPENGL_MAY_HAVE_BIND_SAMPLER
00642     if (bd->GlVersion >= 330 || bd->GlProfileIsES3)
00643         glBindSampler(0, last_sampler);
00644 #endif
00645     glActiveTexture(last_active_texture);
00646 #ifdef IMGUI_IMPL_OPENGL_USE_VERTEX_ARRAY
00647     glBindVertexArray(last_vertex_array_object);
00648 #endif
00649     glBindBuffer(GL_ARRAY_BUFFER, last_array_buffer);
00650 #ifndef IMGUI_IMPL_OPENGL_USE_VERTEX_ARRAY
00651     glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, last_element_array_buffer);
00652     last_vtx_attrib_state_pos.SetState(bd->AttribLocationVtxPos);
00653     last_vtx_attrib_state_uv.SetState(bd->AttribLocationVtxUV);
00654     last_vtx_attrib_state_color.SetState(bd->AttribLocationVtxColor);
00655 #endif
00656     glBlendEquationSeparate(last_blend_equation_rgb, last_blend_equation_alpha);
00657     glBlendFuncSeparate(last_blend_src_rgb, last_blend_dst_rgb, last_blend_src_alpha, last_blend_dst_alpha);
00658     if (last_enable_blend) glEnable(GL_BLEND); else glDisable(GL_BLEND);
00659     if (last_enable_cull_face) glEnable(GL_CULL_FACE); else glDisable(GL_CULL_FACE);
00660     if (last_enable_depth_test) glEnable(GL_DEPTH_TEST); else glDisable(GL_DEPTH_TEST);
00661     if (last_enable_stencil_test) glEnable(GL_STENCIL_TEST); else glDisable(GL_STENCIL_TEST);
00662     if (last_enable_scissor_test) glEnable(GL_SCISSOR_TEST); else glDisable(GL_SCISSOR_TEST);
00663 #ifdef IMGUI_IMPL_OPENGL_MAY_HAVE_PRIMITIVE_RESTART
00664     if (bd->GlVersion >= 310) { if (last_enable_primitive_restart) glEnable(GL_PRIMITIVE_RESTART); else glDisable(GL_PRIMITIVE_RESTART); }
00665 #endif
00666 
00667 #ifdef IMGUI_IMPL_OPENGL_MAY_HAVE_POLYGON_MODE
00668     // Desktop OpenGL 3.0 and OpenGL 3.1 had separate polygon draw modes for front-facing and back-facing faces of polygons
00669     if (bd->HasPolygonMode) { if (bd->GlVersion <= 310 || bd->GlProfileIsCompat) { glPolygonMode(GL_FRONT, (GLenum)last_polygon_mode[0]); glPolygonMode(GL_BACK, (GLenum)last_polygon_mode[1]); } else { glPolygonMode(GL_FRONT_AND_BACK, (GLenum)last_polygon_mode[0]); } }
00670 #endif // IMGUI_IMPL_OPENGL_MAY_HAVE_POLYGON_MODE
00671 
00672     glViewport(last_viewport[0], last_viewport[1], (GLsizei)last_viewport[2], (GLsizei)last_viewport[3]);
00673     glScissor(last_scissor_box[0], last_scissor_box[1], (GLsizei)last_scissor_box[2], (GLsizei)last_scissor_box[3]);
00674     (void)bd; // Not all compilation paths use this
00675 }

00398 {
00399     ImGui_ImplOpenGL3_Data* bd = ImGui_ImplOpenGL3_GetBackendData();
00400     IM_ASSERT(bd != nullptr && "No renderer backend to shutdown, or already shutdown?");
00401     ImGuiIO& io = ImGui::GetIO();
00402 
00403     ImGui_ImplOpenGL3_ShutdownPlatformInterface();
00404     ImGui_ImplOpenGL3_DestroyDeviceObjects();
00405     io.BackendRendererName = nullptr;
00406     io.BackendRendererUserData = nullptr;
00407     io.BackendFlags &= ~(ImGuiBackendFlags_RendererHasVtxOffset | ImGuiBackendFlags_RendererHasViewports);
00408     IM_DELETE(bd);
00409 }
